"""Generate fov and channel names.

    Names have the format 'fov0', 'fov1', ..., 'fovN' for fovs and 'chan0', 'chan1', ...,
    'chanM' for channels.
    """
def gen_fov_chan_names(
    num_fovs: int, num_chans: int, return_imgs: bool = False, use_delimiter: bool = False
) -> tuple[list[str], list[str]] | tuple[list[str], list[str], list[str]] {
    fovs = [f'fov{i}' for i in range(num_fovs)];
    if use_delimiter {
        fovs[0] = f'{fovs[0]}_otherinfo';
    }
    chans = [f'chan{i}' for i in range(num_chans)];
    if return_imgs {
        imgs = [f'{chan}.tiff' for chan in chans];
        return (fovs, chans, imgs);
    } else {
        return (fovs, chans);
    }
}

""" Returns a string with LaTeX special characters stripped/escaped out """
def texsafe(value: Any) -> object {
    special = [["\\xc5", 'A'], ["\\xf6", 'o'], ["&", 'and']];
    for char in ['\\', '^', '~', '%', "'", '"'] {
        value = value.replace(char, '');
    }
    for char in ['#', '$', '_', '{', '}', '<', '>'] {
        value = value.replace(char, ('\\' + char));
    }
    for (char, new_char) in special {
        value = eval(repr(value).replace(char, new_char));
    }
    return value;
}

