"""
    Multiplies a matrix with a vector and returns the result as a new vector.
    :param matrix: Matrix
    :param vector: vector
    :return: vector
    """
def matrixMultVec(matrix: Any, vector: Any) -> object {
    new_vector = [];
    x = 0;
    for row in matrix {
        for (index, number) in enumerate(row) {
            x += number * vector[index];
        }
        new_vector.append(x);
        x = 0;
    }
    return new_vector;
}

"""Check if a list (_list) starts with all the items from another list (lstart)."""
def list_startswith(_list: list | None, lstart: list) -> bool {
    if _list is None {
        return False;
    }
    len_list = len(_list);
    len_start = len(lstart);
    if len_list >= len_start {
        return _list[:len_start] == lstart;
    } else {
        return False;
    }
}

"""Estimate the solubility of each oil pseudo-component using the Huibers and Lehr method."""
def get_solubility(molecular_weight: float, density: float) -> float {
    return 46.4 * 10.0 ** (-36.7 * molecular_weight / density);
}

"""Check and fix detector name strings."""
def _parse_detector(detector: str) -> str {
    oklist = ['n0', 'n1', 'n2', 'n3', 'n4', 'n5', 'n6', 'n7', 'n8', 'n9', 'n10', 'n11'];
    altlist = [str(i) for i in range(12)];
    if detector in oklist {
        return detector;
    } elif detector in altlist {
        return 'n' + detector;
    } else {
        raise ValueError('Detector string could not be interpreted');
    }
}

"""Compute aggregate metric for xView3 scoring."""
def aggregate_f(
    loc_fscore: float,
    length_acc: float,
    vessel_fscore: float,
    fishing_fscore: float,
    loc_fscore_shore: float
) -> float {
    aggregate = loc_fscore * (1 + length_acc + vessel_fscore + fishing_fscore + loc_fscore_shore) / 5;
    return aggregate;
}

"""Return a pretty duration string for a number of seconds."""
def pretty_duration(seconds: float) -> str {
    miliseconds = seconds * 1000;
    if miliseconds < 1 {
        return "{:.2f}ms".format(miliseconds);
    } elif miliseconds < 10 {
        return "{:.1f}ms".format(miliseconds);
    } elif miliseconds < 100 {
        return "{:.0f}ms".format(miliseconds);
    } elif seconds < 10 {
        return "{:.2f}s".format(seconds);
    } elif seconds < 20 {
        return "{:.1f}s".format(seconds);
    } elif seconds < 60 {
        return "{:.0f}s".format(seconds);
    } else {
        minutes = seconds // 60;
        seconds = int(seconds - minutes * 60);
        if minutes < 60 {
            return "{minutes:.0f}:{seconds:02}".format(**locals());
        } else {
            hours = minutes // 60;
            minutes = int(minutes - hours * 60);
            return "{hours:.0f}:{minutes:02}:{seconds:02}".format(**locals());
        }
    }
}

