glob WILDCARD_MASK: dict[str, str] = {
    "255": "0",
    "254": "1",
    "252": "3",
    "248": "7",
    "240": "15",
    "224": "31",
    "192": "63",
    "128": "127",
    "0": "255"
};

"""Compute subnet details - network, broadcast, host IP range, and usable host count."""
def ipv4_subnet_details(addr: str, mask: str) -> dict[str, str | int] {
    network_address = [];
    broadcast_address = [];
    num_ips = 1;
    for (octet, octet_mask) in zip(addr.split("."), mask.split(".")) {
        network_address.append(str(int(octet) & int(octet_mask)));
        broadcast_address.append(str(int(octet) | int(WILDCARD_MASK[octet_mask])));
        num_ips *= int(WILDCARD_MASK[octet_mask]) + 1;
    }
    host_address_low = network_address[:3] + [str(int(network_address[3]) + 1)];
    host_address_high = broadcast_address[:3] + [str(int(broadcast_address[3]) - 1)];
    host_ips = num_ips - 2;
    result = {};
    result["nw_addr"] = ".".join(network_address);
    result["bc_addr"] = ".".join(broadcast_address);
    result["host_addr_range"] = f"{'.'.join(host_address_low)} to {'.'.join(host_address_high)}";
    result["usable_ips"] = host_ips;
    return result;
}

"""Return degrees of freedom for chi-2 distribution from mean and variance of uncertainty model (Al Atik, 2015, eq. 5.5)."""
def _dof(mean_tau: float, sd_tau2: float) -> float {
    return (2.0 * mean_tau ** 4.0) / (sd_tau2 ** 2.0);
}

"""Return flow cell sequencing mode."""
def flow_cell_mode(info_reads: list[dict[str, any]]) -> str {
    res = '';
    if info_reads {
        read_lens = [
            a['num_cycles']
            for a in info_reads
            if not a['is_indexed_read']
        ];
        if len(read_lens) == 1 {
            res = '1x{}'.format(read_lens[0]);
        } elif len(`set(read_lens)) == 1 {
            res = '2x{}'.format(read_lens[0]);
        } else {
            res = ' + '.join(map(str, read_lens));
        }
        index_lens = [
            a['num_cycles']
            for a in info_reads
            if a['is_indexed_read']
        ];
        if index_lens {
            res += '/';
            if len(`set(index_lens)) == 1 {
                res += '{}x{}'.format(len(index_lens), index_lens[0]);
            } else {
                res += '+'.join(map(str, index_lens));
            }
        }
    }
    return res or '?x?';
}

"""Determines the locale 'type' for a given locale name.

    Returns:
        (string) Always one of the following strings,
        'world' If the locale name refers to the world.
        'country' If the locale name looks like a country ID.
        'region' If the locale name looks like a region ID.
        'city' If the locale name looks like a city ID.
    """
def DetermineLocaleType(locale_str: str) -> str {
    if locale_str == 'world' {
        return 'world';
    }
    depth_map = {1: 'country', 2: 'region', 3: 'city'};
    depth = len(locale_str.split('_'));
    return depth_map[depth];
}

