def Mceta(m1: float, m2: float) -> tuple {
    Mc = (m1 * m2) ** (3.0 / 5.0) * (m1 + m2) ** (-1.0 / 5.0);
    eta = m1 * m2 / (m1 + m2) / (m1 + m2);
    return (Mc, eta);
}

