"""Sum the digits that match the one half way around a cyclic string."""
def captcha_halfway(numbers: str) -> int {
    total = 0;
    half = len(numbers) // 2;
    for i in range(half) {
        if numbers[i] == numbers[i + half] {
            total += int(numbers[i]);
        }
    }
    return total * 2;
}

