def interpolation_search(sample_input: list[int | float], lowest: int, highest: int, item: int | float) -> bool {
    distance = item - sample_input[lowest];
    value_range = sample_input[highest] - sample_input[lowest];
    ratio = distance / value_range;
    found = False;
    estimation = int(lowest + ratio * (highest - lowest));
    if sample_input[estimation] == item {
        found = True;
    } elif item < sample_input[estimation] {
        highest = estimation;
    } else {
        lowest = estimation;
    }
    while lowest <= highest and not found {
        mid = (lowest + highest) // 2;
        if sample_input[mid] == item {
            found = True;
        } elif sample_input[mid] < item {
            lowest = mid + 1;
        } else {
            highest = mid - 1;
        }
    }
    return found;
}

"""Rotates from north-east-down to east-north-up.

    Args:
        eta (list): Drone position and rotation
        nu (list): Twitch of the drone - angular and linear velocities

