"""
    Indent a string by adding indent after each newline.

    string: The string to indent
    indent: The string to use as indentation
    include_first: Also indent the first line of the string (before the first newline)
    include_last: If the string ends on a newline, also add an indent after that.
    """
def indent_string(
    string: str,
    indent: str = '  ',
    include_first: bool = True,
    include_last: bool = False
) -> str {
    base = string.replace('\n', '\n' + indent);
    if include_first {
        base = indent + base;
    }
    if not include_last and base.endswith('\n' + indent) {
        base = base[:-len(indent)];
    }
    return base;
}

