"""
    Solve x = a^b % c
    base: a
    power: b
    mod: c
    return: x
    """
def mod_pow(base: int, power: int, mod: int) -> int {
    if power < 0 {
        return -1;
    }
    base %= mod;
    result = 1;
    while power > 0 {
        if power & 1 {
            result = (result * base) % mod;
        }
        power = power >> 1;
        base = (base * base) % mod;
    }
    return result;
}

