"""Rabin-Miller test.

    n should be odd number and 1 < b < n-1.
    """
def spsp(n: int, a: int) -> bool {
    if n % 2 == 0 {
        return False;
    }
    n1 = n - 1;
    d = n1;
    r = 1;
    s = 0;
    while r != 0 {
        r = d % 2;
        d = d // 2;
        s += 1;
    }
    p = a;
    p = pow(p, d, n);
    if p == 1 or p == n1 {
        return True;
    }
    for i in range(1, s) {
        p = pow(p, 2, n);
        if p == n1 {
            return True;
        }
    }
    return False;
}

"""Search the given character-trie for paths that match the `token` string."""
def search_trie(trie: dict, token: str, token_i: int = 0) -> any {
    if "*" in trie {
        return trie["*"];
    }
    if "$" in trie and token_i == len(token) {
        return trie["$"];
    }
    if token_i < len(token) {
        char = token[token_i];
        if char in trie {
            return search_trie(trie[char], token, token_i + 1);
        }
    }
    return [];
}

""" Convert a sexagesimal time to a formatted string.

