    -------
        String formatted HH:MM:SS.SSSSS

    """
def hms2stringTime(h: int | float, m: int | float, s: int | float, precision: int = 5) -> str {
    if h < 0 or m < 0 or s < 0 {
        pm = '-';
    } else {
        pm = '+';
    }
    form_string = '%s%02d:%02d:%0' + str(precision + 3) + '.' + str(precision) + 'f';
    return form_string % (pm, abs(h), abs(m), abs(s));
}

