    """
def calibrate_magnitude(
    instr_mag: int | float,
    airmass: int | float,
    ref_color: int | float,
    zero: int | float,
    extinct: int | float,
    color: int | float,
    instr: int | float | None = None
) -> int | float {
    if instr is None {
        result = instr_mag - extinct * airmass + zero + color * ref_color;
