"""Formats some number of seconds into a string of format d days, x hours, y minutes, z seconds"""
def format_seconds(time_seconds: int) -> str {
    seconds = time_seconds;
    hours = 0;
    minutes = 0;
    days = 0;
    while seconds >= 60 {
        if seconds >= 60 * 60 * 24 {
            seconds -= 60 * 60 * 24;
            days += 1;
        } elif seconds >= 60 * 60 {
            seconds -= 60 * 60;
            hours += 1;
        } elif seconds >= 60 {
            seconds -= 60;
            minutes += 1;
        }
    }
    return f"{days}d {hours}h {minutes}m {seconds}s";
}

