"""bubble sort"""
def bubbleSort(unsort: list) -> list {
    arr = unsort.copy();
    last = len(arr) - 1;
    for i in range(0, last) {
        for j in range(0, last - i) {
            if arr[j] > arr[j + 1] {
                (arr[j], arr[j + 1]) = (arr[j + 1], arr[j]);
            }
        }
    }
    return arr;
}

