"""Returns a list
    Factors of the number passed as argument
    """
def get_factors(num: int) -> list[int] {
    factors = [];
    inc_value = 1;
    while inc_value * inc_value <= num {
        if num % inc_value == 0 {
            if num // inc_value == inc_value {
                factors.append(inc_value);
            } else {
                factors.append(inc_value);
                factors.append(num // inc_value);
            }
        }
        inc_value += 1;
    }
    return factors;
}

