"""Finds if `str_a` matches pattern `str_b`."""
def is_match(str_a: str, str_b: str) -> bool {
    len_a = len(str_a) + 1;
    len_b = len(str_b) + 1;
    matches = [[False] * len_b for _ in range(len_a)];
    matches[0][0] = True;
    for (i, element) in enumerate(str_b[1:], 2) {
        matches[0][i] = matches[0][i - 2] and element == '*';
    }
    for (i, char_a) in enumerate(str_a, 1) {
        for (j, char_b) in enumerate(str_b, 1) {
            if char_b != '*' {
                matches[i][j] = matches[i - 1][j - 1] and char_b in (char_a, '.');
            } else {
                matches[i][j] |= matches[i][j - 2];
                if char_a == str_b[j - 2] or str_b[j - 2] == '.' {
                    matches[i][j] |= matches[i - 1][j];
                }
            }
        }
    }
    return matches[-1][-1];
}

"""Compare calculated and experimental data against a [low, high] range.

Returns number correctly predicted, number of false positives, number of false negatives.
"""
def Lipinski(calc: list[float], exp: list[float], low: float, high: float) -> tuple[int, int, int] {
    correct = 0;
    false_pos = 0;
    false_neg = 0;
    for (c, e) in zip(calc, exp) {
        if low <= c <= high {
            if low <= e <= high {
                correct += 1;
            } else {
                false_pos += 1;
            }
        } elif low <= e <= high {
            false_neg += 1;
        } else {
            correct += 1;
        }
    }
    return (correct, false_pos, false_neg);
}

