    :param window_width:sliding window size
    :return: all max number
    """
def max_in_sliding_window(array: list[int], window_width: int) -> list[int] | None {
    if not array or window_width < 1 {
        return None;
    }
    max_i = [];
    res = [];
    for i in range(len(array)) {
        while max_i and array[i] >= array[max_i[-1]] {
            max_i.pop();
        }
        max_i.append(i);
        while max_i and i - max_i[0] >= window_width {
            max_i.pop(0);
        }
        if window_width - 1 <= i {
            res.append(array[max_i[0]]);
        }
    }
    return res;
}

"""
    Generates Lorenz strange attractor.
    """
def lorenz(
    num_points: int = 15000,
    start: list[float] = [0.1, 0.1, 0.1],
    scaling_factor: float = 20,
    delta: float = 0.008,
    a: float = 0.1,
    b: float = 4.0,
    c: float = 14.0,
    d: float = 0.08
) -> list[float] {
    verts = [];
    x = start[0];
    y = start[1];
    z = start[2];
    for i in range(0, num_points) {
        dx = -a * x + y * y - z * z + a * c;
        dy = x * (y - b * z) + d;
        dz = z + x * (b * y + z);
        x = x + delta * dx;
        y = y + delta * dy;
        z = z + delta * dz;
        verts.extend([x * scaling_factor, z * scaling_factor, y * scaling_factor]);
    }
    return verts;
}

