glob UVARINT_LOW7_MASK = 0x7F;
glob UVARINT_CONT_BIT = 0x80;

"""Pack an unsigned variable-length integer into bytes."""
def _pack_uvarint(n: int) -> bytes {
    result = b'';
    while True {
        chunk = n & UVARINT_LOW7_MASK;
        n >>= 7;
        if n {
            result += `bytes((chunk | UVARINT_CONT_BIT,));
        } else {
            result += `bytes((chunk,));
            break;
        }
    }
    return result;
}

