"""Put the largest element to the rightmost position each time."""
def bubble_sort(lis: list) -> list {
    j = 0;
    done = False;
    while not done {
        done = True;
        for i in range(len(lis) - j - 1) {
            if lis[i] > lis[i + 1] {
                (lis[i], lis[i + 1]) = (lis[i + 1], lis[i]);
                done = False;
            }
        }
        j += 1;
    }
    return lis;
}

