def merge(a: list, b: list) -> list {
    merged = [];
    i = 0;
    j = 0;
    while i < len(a) and j < len(b) {
        if a[i] < b[j] {
            merged.append(a[i]);
            i += 1;
        } else {
            merged.append(b[j]);
            j += 1;
        }
    }
    merged += a[i:];
    merged += b[j:];
    return merged;
}

