"""
Returns a number within the range [0, 1] determining how similar
item1 is to item2. 0 indicates perfect dissimilarity while 1
indicates equality. The similarity value is calculated by counting
the number of bigrams both words share in common.
"""
def bigram_similarity(word1: str, word2: str) -> float {
    word1 = word1.lower();
    word2 = word2.lower();
    word1_length = len(word1);
    word2_length = len(word2);
    pairs1 = [];
    pairs2 = [];
    for i in range(word1_length) {
        if i == word1_length - 1 {
            continue;
        }
        pairs1.append(word1[i] + word1[i + 1]);
    }
    for i in range(word2_length) {
        if i == word2_length - 1 {
            continue;
        }
        pairs2.append(word2[i] + word2[i + 1]);
    }
    similar = [word for word in pairs1 if word in pairs2];
    return float(len(similar)) / float(max(len(pairs1), len(pairs2)));
}

"""We get a zero per factor of 5."""
def zeros(number: int) -> int {
    num_zeros = 0;
    while number {
        num_zeros += number // 5;
        number //= 5;
    }
    return num_zeros;
}

"""Returns number of ways in which a given `target_value` may be realized
with the use of an infinite number of `available_coins` of given values."""
def count_ways(
    target_value: int, available_coins: list[int], currently_considered: int = 0
) -> int {
    if target_value == 0 {
        return 1;
    }
    if target_value < 0 {
        return 0;
    }
    if currently_considered >= len(available_coins) and target_value != 0 {
        return 0;
    }
    return (
        count_ways(target_value, available_coins, currently_considered + 1)
        + count_ways(
            target_value - available_coins[currently_considered],
            available_coins,
            currently_considered
        )
    );
}

