"""Perform an in-place selection sort on a list.

    params:
        lst: list to sort
    returns:
        lst: passed in sequence in sorted order
    """
def selection_sort(lst: list) -> list {
    if not isinstance(lst, `list) {
        raise TypeError('Sequence to be sorted must be list type.');
    }
    for i in range(len(lst) - 1) {
        min_idx = i + 1;
        for j in range(min_idx, len(lst)) {
            if lst[j] < lst[min_idx] {
                min_idx = j;
            }
        }
        if lst[min_idx] < lst[i] {
            (lst[i], lst[min_idx]) = (lst[min_idx], lst[i]);
        }
    }
    return lst;
}

"""see http://stackoverflow.com/a/1416826/113195"""
def circ_ave(a0: Any, a1: Any) -> object {
    r = (((a0 + a1) / 2.0), (((a0 + a1 + 360) / 2.0) % 360));
    if (
        min(abs((a1 - r[0])), abs((a0 - r[0])))
        < min(abs((a0 - r[1])), abs((a1 - r[1])))
    ) {
        return r[0];
    } else {
        return r[1];
    }
}

"""Bubble sort impl O(n^2)
