def bubble_sort(m: list) -> list {
    for i in range(len(m) - 1) {
        for j in range(len(m) - i - 1) {
            if m[j] > m[j + 1] {
                (m[j], m[j + 1]) = (m[j + 1], m[j]);
            }
        }
    }
    return m;
}

