"""<line> ::= <color> contain <contents>"""
def parse_line(line: str) -> tuple {
    tokens = line.replace(",", " COMMA").replace(".", " PERIOD").split();
    tokens = `list(reversed(tokens));
    def eat(*expected: str) -> None {
        assert tokens.pop() in expected;
    }
    """<color> ::= <word> <word> (bag|bags)""";
    def parse_color() -> str {
        res = "{} {}".format(tokens.pop(), tokens.pop());
        eat("bag", "bags");
        return res;
    }
    """<contents> ::= contain (no other bags|<bag-amount-list>) PERIOD""";
    def parse_contents() -> list {
        assert tokens.pop() == "contain";
        if tokens[-1] == "no" {
            eat("no");
            eat("other");
            eat("bags");
            res = [(0, None)];
        } else {
            res = parse_bag_amount_list();
        }
        eat("PERIOD");
        return res;
    }
    """<bag-amount-list> ::= <integer> <color> (COMMA <integer> <color>)*""";
    def parse_bag_amount_list() -> list {
        res = [];
        am = int(tokens.pop());
        col = parse_color();
        res.append((am, col));
        while tokens[-1] == "COMMA" {
            eat("COMMA");
            am = int(tokens.pop());
            col = parse_color();
            res.append((am, col));
        }
        return res;
    }
    col = parse_color();
    contents = parse_contents();
    assert not tokens;
    return (col, contents);
}

"""Format a seconds count as a human readable interval string.

:param seconds: seconds count
:param prefix: prefix for print
:return: human readable representation of interval
"""
def print_seconds_nice(seconds: int | float, prefix: str = "") -> str {
    if seconds < 60 {
        return "{}{}s".format(prefix, seconds);
    }
    minutes = seconds // 60;
    seconds -= minutes * 60;
    if minutes < 60 {
        seconds = round(seconds, 2);
        return "{}{}m {}s".format(prefix, minutes, seconds);
    }
    hours = minutes // 60;
    minutes -= hours * 60;
    if hours < 24 {
        minutes = int(minutes);
        seconds = round(seconds, 2);
        return "{}{}h {}m {}s".format(prefix, hours, minutes, seconds);
    }
    days = hours // 24;
    hours -= days * 24;
    seconds = round(seconds, 2);
    return "{}{}d {}h {}m {}s".format(prefix, days, hours, minutes, seconds);
}

