"""Performs the MSB base-128 decoding of a given value (varint decode from LevelDB)."""
def b128_decode(data: any) -> int {
    n = 0;
    i = 0;
    while True {
        d = int(data[2 * i:2 * i + 2], 16);
        n = n << 7 | d & 0x7F;
        if d & 0x80 {
            n += 1;
            i += 1;
        } else {
            return n;
        }
    }
}

