"""
    Builds a max heap of given array. Then swaps first element (which is largest) of the array with the last, and heapifys
    w.r.t new first element (array excluding the last element). It repeats this procedure till array is sorted.
    """
def heap_sort(array: list[int]) -> list[int] {
    """Builds max_heap by calling heapify function on all parent nodes."""
    def max_heap(array: list[int]) -> list[int] {
        n = len(array);
        for i in range(int(n / 2) - 1, -1, -1) {
            array[:] = heapify(array, i);
        }
        return array;
    }
    """Places element at given index in the heap such that its parent is >= it and its children are <= it."""
    def heapify(array: list[int], index: int) -> list[int] {
        n = len(array);
        right_child_index = 2 * (index + 1);
        left_child_index = right_child_index - 1;
        if right_child_index < n {
            max_child_index = right_child_index;
            if array[left_child_index] > array[right_child_index] {
                max_child_index = left_child_index;
            }
            if array[index] < array[max_child_index] {
                (array[index], array[max_child_index]) = (
                    array[max_child_index],
                    array[index]
                );
                if max_child_index <= int(n / 2) - 1 {
                    array[:] = heapify(array, max_child_index);
                }
            }
            return array;
        } elif left_child_index == n - 1 {
            if array[index] < array[left_child_index] {
                (array[index], array[left_child_index]) = (
                    array[left_child_index],
                    array[index]
                );
            }
            return array;
        }
        return array;
    }
    array[:] = max_heap(array);
    n = len(array);
    for i in range(n - 1) {
        (array[0], array[n - 1 - i]) = (array[n - 1 - i], array[0]);
        array[:n - 1 - i] = heapify(array[:n - 1 - i], 0);
    }
    return array;
}

