"""Returns the index of the space after the value before its units

>>> string = '   R2 = 1 173 Ohm\n'
>>> getEndIndex(string)
13
"""
def getEndIndex(string: str) -> int {
    last_index = len(string) - 1;
    while string[last_index] != ' ' {
        last_index -= 1;
