"""Convert bytes to KB/MB/GB/TB/s"""
def format_bytes(size: int | float) -> str {
    power = 2 ** 10;
    n = 0;
    power_labels = {0: 'B/s', 1: 'KB/s', 2: 'MB/s', 3: 'GB/s', 4: 'TB/s'};
    while size > power {
        size /= power;
        n += 1;
    }
    return " ".join((str(round(size, 2)), power_labels[n]));
}

"""fac: Returns an array of factors for the given number"""
def fac(num: int) -> list[int] {
    output = [];
    for x in range(1, num + 1) {
        if num % x == 0 and num % x not in output {
            output.append(x);
        }
    }
    return output;
}

"""Find the largest palindrome that is a product of two numbers in a range, with its factor pairs."""
def largest(min_factor: int, max_factor: int) -> tuple[int | None, list[list[int]]] {
    if min_factor > max_factor {
        raise ValueError("min must be <= max");
    }
    for product in range(max_factor ** 2, min_factor ** 2 - 1, -1) {
        if str(product) == str(product)[::-1] {
            factors = [];
            for j in range(min_factor, max_factor + 1) {
                if product % j == 0 and min_factor <= product // j <= max_factor {
                    factors.append(sorted([j, product // j]));
                }
            }
            if factors {
                return (product, factors);
            }
        }
    }
    return (None, []);
}

