"""Calculate the mean based upon the previous mean and update incrementally."""
def incremental_mean(prev_mean: int | float, new_vals: list[int | float]) -> int | float {
    mean = prev_mean;
    n = len(new_vals);
    for x in new_vals {
        mean = mean + (x - mean) / n;
    }
    return mean;
}

