"""Recursively convert a dict's keys to strings."""
def stringify_keys(d: dict) -> dict {
    if not isinstance(d, `dict) {
        return d;
    }
    def decode(k: any) -> str {
        if isinstance(k, str) {
            return k;
        }
        try {
            return k.decode("utf-8");
        } except Exception {
            return repr(k);
        }
    }
    return {decode(k): stringify_keys(v) for (k, v) in d.items()};
}

