"""
    is_prime returns True if N is a prime number, False otherwise

    Parameters:
       Input, integer N, the number to be checked.

       Output, boolean value, True or False
    """
def is_prime(n: int | float) -> bool {
    if n != int(n) or n < 1 {
        return False;
    }
    p = 2;
    while p < n {
        if n % p == 0 {
            return False;
        }
        p += 1;
    }
    return True;
}

"""
    Takes a list of numbers and returns a list of unique values, subject to a threshold difference.
    """
def sloppyUnique(t: list[float], thresholdSeconds: float) -> list[float] {
    sloppy_list = [t[0]];
    for i in range(1, len(t)) {
        keepit = True;
        for j in range(0, i) {
            if abs(t[i] - t[j]) < thresholdSeconds {
                keepit = False;
            }
        }
        if keepit {
            sloppy_list.append(t[i]);
        }
    }
    return sloppy_list;
}

"""Quadratic interpolation for estimating the true position of an
    inter-sample maximum when nearby samples are known.

    f is a vector and x is an index for that vector.

    Returns (vx, vy), the coordinates of the vertex of a parabola that goes
    through point x and its two neighbors.
    """
def parabolic(f: list[float], x: int) -> tuple[float, float] | None {
    if x < 1 or x + 1 >= len(f) {
        return None;
    }
    denom = f[x - 1] - 2 * f[x] + f[x + 1];
    if denom == 0.0 {
        return None;
    }
    xv = (1 / 2.0) * (f[x - 1] - f[x + 1]) / denom + x;
    yv = f[x] - (1 / 4.0) * (f[x - 1] - f[x + 1]) * (xv - x);
    return (xv, yv);
}

