"""Returns the Dot product between two sorted vectors of bit ids."""
def Dot(v1: tuple[int, ...], v2: tuple[int, ...]) -> int {
    res = 0;
    n_v1 = len(v1);
    n_v2 = len(v2);
    i = 0;
    j = 0;
    while i < n_v1 {
        v1_val = v1[i];
        v1_count = 1;
        i += 1;
        while i < n_v1 and v1[i] == v1_val {
            v1_count += 1;
            i += 1;
        }
        while j < n_v2 and v2[j] < v1_val {
            j += 1;
        }
        if j < n_v2 and v2[j] == v1_val {
            v2_count = 1;
            j += 1;
            while j < n_v2 and v2[j] == v1_val {
                v2_count += 1;
                j += 1;
            }
            common_count = min(v1_count, v2_count);
            res += common_count * common_count;
        } elif j >= n_v2 {
            break;
        }
    }
    return res;
}

