def convert2Frequency(featureDict: dict) -> dict {
    if sum(featureDict.values()) != 0 {
        invTotalNumber = 1.0 / sum(featureDict.values());
    } else {
        invTotalNumber = 1.0;
    }
    featureDict.update((k, invTotalNumber * v) for (k, v) in featureDict.items());
    return featureDict;
}

