"""Calculate the contrast ratio between a foreground color (with optional alpha) and a background color."""
def color_contrast_ratio(fore_color: list[float], back_color: list[float]) -> float {
    """Helper function to calculate luminance for one channel of rgb"""
    def _calculate_luminance(color_code: float) -> float {
        index = float(color_code) / 255;
        if index < 0.03928 {
            return index / 12.92;
        } else {
            return ((index + 0.055) / 1.055) ** 2.4;
        }
    }
    """Helper function to calculate luminance for all channels of rgb"""
    def _calculate_relative_luminance(rgb: list[float]) -> float {
        return (
            0.2126 * _calculate_luminance(rgb[0])
            + 0.7152 * _calculate_luminance(rgb[1])
            + 0.0722 * _calculate_luminance(rgb[2])
        );
    }
    light = back_color if sum(back_color[0:3]) >= sum(fore_color[0:3]) else fore_color;
    dark = back_color if sum(back_color[0:3]) < sum(fore_color[0:3]) else fore_color;
    contrast_ratio = (
        (_calculate_relative_luminance(light) + 0.05)
        / (_calculate_relative_luminance(dark) + 0.05)
    );
    if len(fore_color) == 4 {
        contrast_ratio = float(fore_color[3]) * (contrast_ratio - 1) + 1;
    }
    return contrast_ratio;
}

