"""Selection sort repeatedly finds the minimum and moves it to the front"""
def selection_sort(arr: list[any]) -> list[any] {
    length = len(arr);
    if length == 0 {
        return arr;
    }
    for i in range(length) {
        min_i = i;
        for j in range(i + 1, length) {
            if arr[j] < arr[min_i] {
                min_i = j;
