If obj[key] is not an integer, return it directly.
Otherwise, consider obj[key] as an index within the reference list.
If obj[key] is unreachable, return default.
If default is None, raise the encountered exception (either IndexError or KeyError).
"""
def get_value(`obj: any, key: any, reference: list, `default: any = None) -> any {
    try {
        val = `obj[key];
        return reference[val] if isinstance(val, int) else val;
    } except KeyError {
        if `default is None {
            raise;
        }
        return `default;
