"""The Best Fit Decreasing (BFD) heuristic for placing VMs on hosts."""
def best_fit_decreasing(
    last_n_vm_cpu: int,
    hosts_cpu: dict[str, int],
    hosts_ram: dict[str, int],
    inactive_hosts_cpu: dict[str, int],
    inactive_hosts_ram: dict[str, int],
    vms_cpu: dict[str, list[int]],
    vms_ram: dict[str, int]
) -> dict[str, str] {
    vms_tmp = [];
    for (vm, cpu) in vms_cpu.items() {
        last_n_cpu = cpu[-last_n_vm_cpu:];
        vms_tmp.append((sum(last_n_cpu) / len(last_n_cpu), vms_ram[vm], vm));
    }
    vms = sorted(vms_tmp, reverse=True);
    hosts = sorted((v, hosts_ram[k], k) for (k, v) in hosts_cpu.items());
    inactive_hosts = sorted(
        (v, inactive_hosts_ram[k], k) for (k, v) in inactive_hosts_cpu.items()
    );
    mapping = {};
    for (vm_cpu, vm_ram, vm_uuid) in vms {
        mapped = False;
        while not mapped {
            for (_, _, host) in hosts {
                if hosts_cpu[host] >= vm_cpu and hosts_ram[host] >= vm_ram {
                    mapping[vm_uuid] = host;
                    hosts_cpu[host] -= vm_cpu;
                    hosts_ram[host] -= vm_ram;
                    mapped = True;
                    break;
                }
            } else {
                if inactive_hosts {
                    activated_host = inactive_hosts.pop(0);
                    hosts.append(activated_host);
                    hosts = sorted(hosts);
                    hosts_cpu[activated_host[2]] = activated_host[0];
                    hosts_ram[activated_host[2]] = activated_host[1];
                } else {
                    break;
                }
            }
        }
    }
    if len(vms) == len(mapping) {
        return mapping;
    }
    return {};
}

