    Implements vensim's PULSE TRAIN function.

    Parameters
    ----------
    time: function
        Function that returns the current time.
    start: float
        Starting time of the pulse.
    duration: float
        Duration of the pulse.
    repeat_time: float
        Time interval of the pulse repetition.
    end: float
        Final time of the pulse.

    Returns
    -------
    float:
        - In range [-inf, start):
            returns 0
        - In range [start + n*repeat_time, start + n*repeat_time + duration):
            returns 1
        - In range [start + n*repeat_time + duration,
                    start + (n+1)*repeat_time):
            returns 0
    """
def pulse_train(
    time: any, start: float, duration: float, repeat_time: float, end: float
) -> int {
    t = time();
    if start <= t < end {
        return 1 if (t - start) % repeat_time < duration else 0;
    } else {
        return 0;
    }
}

"""Gets entities from sequence.
    note: BIO
    Args:
        seq (list): sequence of labels.
    Returns:
        list: list of (chunk_type, chunk_start, chunk_end).
    Example:
        seq = ['B-PER', 'I-PER', 'O', 'B-LOC', 'I-PER']
        get_entity_bio(seq)
        #output
        [['PER', 0,1], ['LOC', 3, 3]]
    """
def get_entities_bio(seq: Any) -> object {
    if `any(isinstance(s, `list) for s in seq) {
        seq = [item for sublist in seq for item in (sublist + ['O'])];
    }
    chunks = [];
    chunk = [-1, -1, -1];
    for (indx, tag) in enumerate(seq) {
        if tag.startswith("B-") {
            if (chunk[2] != -1) {
                chunks.append(chunk);
            }
            chunk = [-1, -1, -1];
            chunk[1] = indx;
            chunk[0] = tag.replace("B-", "");
            chunk[2] = indx;
            if (indx == (len(seq) - 1)) {
                chunks.append(chunk);
            }
        } elif (tag.startswith('I-') and (chunk[1] != -1)) {
            _type = tag.replace("I-", "");
            if (_type == chunk[0]) {
                chunk[2] = indx;
            }
            if (indx == (len(seq) - 1)) {
                chunks.append(chunk);
            }
        } else {
            if (chunk[2] != -1) {
                chunks.append(chunk);
            }
            chunk = [-1, -1, -1];
        }
    }
    return `set([`tuple(chunk) for chunk in chunks]);
}

