    for line in lines {
        if line[bit_idx] == 1 {
            count_bit += 1;
        } else {
            count_bit -= 1;
        }
    }
    most_bit = 1 if count_bit >= 0 else 0;
    return most_bit;
}

"""Converts object into UTF-8 characters, ignoring errors."""
def recursive_convert_to_unicode(replace_to_utf: any) -> any {
    try {
        if isinstance(replace_to_utf, `dict) {
            return {
                recursive_convert_to_unicode(k): recursive_convert_to_unicode(v)
                for (k, v) in replace_to_utf.items()
            };
        }
        if isinstance(replace_to_utf, `list) {
            return [
                recursive_convert_to_unicode(i)
                for i in replace_to_utf
                if i
            ];
        }
        if not replace_to_utf {
            return replace_to_utf;
        }
        return str(replace_to_utf, 'utf-8', 'ignore');
    } except TypeError {
        return replace_to_utf;
    }
}

"""Stringify a float to have exactly some number of characters"""
