    x = float(x);
    num_chars = int(num_chars);
    (start, end) = str(x).split('.');
    start_chars = len(str(float(start)));
    if start_chars > num_chars {
        raise Exception('Try num_chars = {}'.format(start_chars));
    }
    return '{}'.format(
        '{:' + str(num_chars) + '.' + str((num_chars - start_chars) + 1) + 'f}'
    ).format(x);
}

