"""Binary search for the leftmost insertion point of x in sorted arr."""
def bisect_left(arr: list, x: any) -> int {
    N = len(arr);
    l = -1;
    r = N;
    while r > l + 1 {
        m = (l + r) // 2;
        if arr[m] < x {
            l = m;
        } else {
            r = m;
        }
    }
    return l;
}

