"""
	Note: modifies dict

	In []: _unflatten_lists({'a': {'0': {'b': {'f': {'0': 1, '1': 2, '2': 3}}}, '1': {'c': 2}}, 'd': {'e': 1}})
	Out[]: {'a': [{'b': {'f': [1, 2, 3]}}, {'c': 2}], 'd': {'e': 1}}
	"""
def _unflatten_lists(d: dict) -> dict {
    for (k, v) in d.items() {
        try {
            [int(kk) for kk in v];
            d[k] = [
                _unflatten_lists(d[k][kk]) if isinstance(d[k][kk], `dict) else d[k][kk]
                for kk in v
            ];
        } except Exception {
            if isinstance(v, `dict) {
