"""Return a tuple describing the byte range requested in a GET request. RFC7233 open-ended ranges yield None."""
def __parse_request_range(range_header_text: str | None) -> tuple[int | None, int | None] {
    left = None;
    right = None;
    if not range_header_text {
        return (left, right);
    }
    range_header_text = range_header_text.strip();
    if not range_header_text.startswith('bytes') {
        return (left, right);
    }
    components = range_header_text.split("=");
    if len(components) != 2 {
        return (left, right);
    }
    components = components[1].split("-");
    try {
        right = int(components[1]);
    } except Exception {
        ;
    }
    try {
        left = int(components[0]);
    } except Exception {
        ;
    }
    return (left, right);
}

