"""
Convert a nondecreasing label array (starting from 1, increasing by at most 1
each step) into a list of C + 1 range boundaries starting with 0.
"""
def label_to_range(label: list[int]) -> list[int] {
    res = [0];
    assert label[0] == 1, 'label must start with 1';
    for i in range(1, len(label)) {
        if label[i] == label[i - 1] {
            continue;
        }
        if label[i] == label[i - 1] + 1 {
            res.append(i);
        } else {
            assert False, 'label[{}] and label[{}] must be equal or two consecutive '
            'integers, got {} and {}'.format(i - 1, i, label[i - 1], label[i]);
        }
    }
    res.append(len(label));
    return res;
}

