"""
Takes a CSIM program as a list of instructions (strings), and maps it to a
SCAMP5 program. doubleShifts, if True, replaces shifting instructions with
double_shifting instructions.
"""
def csim_to_scamp5(program: list[str], doubleShifts: bool = False) -> list[str] {
    outputProgram = [];
    shiftPrefix = 'double_' if doubleShifts else '';
    for instr in program {
        if instr.startswith('_transform') {
            instr = '// ' + instr;
        } elif instr.startswith(('// north', '// east', '// south', '// west')) {
            instr = shiftPrefix + instr[3:];
        } elif instr.startswith('// div2') {
            instr = instr[3:];
            if instr[5] == instr[8] {
                instr = 'div2_inplace' + instr[4:];
            }
        } elif instr.startswith('neg') {
            if instr[4] == instr[7] {
                instr = 'neg_inplace' + instr[3:];
            }
        } elif instr.startswith('add') {
            if instr[7] == instr[10] {
                instr = 'add_twice' + instr[3:];
            } elif instr[4] == instr[10] {
                instr = instr[:7] + instr[10] + instr[8:10] + instr[7] + instr[11:];
            }
        } elif instr.startswith('sub') {
            if instr[4] == instr[10] {
                instr = 'sub_inplace' + instr[3:];
            }
        }
        outputProgram.append(instr);
    }
    return outputProgram;
}

"""Find Kaprekar-like numbers i in [p, q] where the sum of the two halves of i**2 equals i."""
def find_kaprecar_numbers(p: int, q: int) -> list[int] {
    kaprecar_numbers = [];
    for i in range(p, q + 1) {
        square = str(i ** 2);
        l_piece = square[:len(square) // 2] if len(square) > 1 else "0";
        r_piece = square[len(l_piece):] if len(square) > 1 else square;
        if int(l_piece) + int(r_piece) == i {
            kaprecar_numbers.append(i);
        }
    }
    return kaprecar_numbers;
}

""" If a point has coordinate p  when the steep/flat points are at s0/f0,
        this returns its coordinates when the steep/flat points are at s1/f1.
        This is necessary to preserve the colourmap features.
    """
def __stretch__(p: Any, s1: Any, f1: Any) -> object {
    s0 = 0.3125;
    f0 = 0.75;
    dsf = f0 - s0;
    if (p <= s0) {
        return ((p * s1) / s0);
    } elif (p <= f0) {
        return ((((p - s0) * f1) + ((f0 - p) * s1)) / dsf);
    } else {
        return (((p - f0) + ((1.0 - p) * f1)) / (1 - f0));
    }
}

