    new = [];
    for x in msg_l {
        if "\n" in x {
            x = x.replace("\n", "");
            new.append(x) if not len(x) == 0 else None;
        } elif len(x) != 0 {
            new.append(x);
        }
    }
    return " ".join(new);
}

"""
    Return row that matches lookup fields.
    """
def _get_matched_row(rows: list[dict], lookup: dict) -> tuple[int | None, dict | None] {
    for (index, row) in enumerate(rows) {
        matched = True;
        for (field, value) in lookup.items() {
            if str(row.get(field, '')).strip() != value {
                matched = False;
                break;
            }
        }
        if matched {
            return (index, row);
        }
    }
    return (None, None);
}

