"""Returns the smallest element from the list that is greater or equal to the value. Return None if not found
    """
def get_smallest_value_greater_or_equal_to(
    iter: (list or range), value: Any
) -> object {
    if (`type(iter) == `list) {
        i = [
            x
            for x in iter
            if (x >= value)
        ];
        return min(i) if i else None;
    } elif (`type(iter) == range) {
        if (value in range(iter.start, iter.stop)) {
            return (
                value + ((iter.step - ((value - iter.start) % iter.step)) % iter.step)
            );
        } elif (value < iter.start) {
            return iter.start;
        } else {
            return None;
        }
    } else {
        raise ValueError("iter must be of type list or range");
    }
}

