"""Return the future value obtained from an amount of cash growing with a fixed interest over a period of time."""
def future_value(interest: float, period: int, cash: int | float) -> float {
    if not 0 <= interest <= 1 {
        raise ValueError('"interest" must be a float between 0 and 1');
    }
    for d in range(period) {
        cash += cash * interest;
    }
    return cash;
}

