"""second degree interpolation used by findApex"""
def secDegInterpolate(
    x1: float, x2: float, x3: float, y1: float, y2: float, y3: float, xfit: float
) -> float {
    x12 = x1 - x2;
    x13 = x1 - x3;
    x23 = x2 - x3;
    xf1 = xfit - x1;
    xf2 = xfit - x2;
    xf3 = xfit - x3;
    yfit = (
        (y1 * x23 * xf2 * xf3 - y2 * x13 * xf1 * xf3 + y3 * x12 * xf1 * xf2)
        / (x12 * x13 * x23)
    );
    return yfit;
}

