return: "[a, b]; [c, d]"
"""
def replace_comma_in_text(text: str) -> str {
    result_text = "";
    replace = True;
    for sign in text {
        if sign == '[' {
            replace = False;
        }
        if sign == ']' {
            replace = True;
        }
        if sign == ',' {
            if replace {
                result_text += ';';
            } else {
                result_text += sign;
            }
        } else {
            result_text += sign;
        }
    }
    return result_text;
}

"""Exchange the smallest prefixes of first and second that have equal sum.

>>> a = [1, 1, 3, 2, 1, 1, 4]
