[4, 3, 1, 1, 4]
>>> b
[1, 1, 3, 2, 2, 7]
>>> c = [3, 3, 2, 4, 1]
>>> trade(b, c)
'No deal!'
>>> b
[1, 1, 3, 2, 2, 7]
>>> c
[3, 3, 2, 4, 1]
>>> trade(a, c)
'Deal!'
>>> a
[3, 3, 2, 1, 4]
>>> b
[1, 1, 3, 2, 2, 7]
>>> c
[4, 3, 1, 4, 1]
"""
def trade(first: list[float], second: list[float]) -> str {
    """
    This function tries to find the indicies that result in an equal sum starting from
    the beginning of the lists. If either sides of the sums are smaller, the respective
    index is incremented. If either of the indicies pass the boundaries of the list, then
    an equal sum cannot be found.
    """;
    def find_equal_sum_partitions(fir: list[float], sec: list[float]) -> tuple[int | None, int | None] {
        fi = 1;
        si = 1;
        while fi < len(fir) and si < len(sec) {
            sumfi = sum(fir[:fi]);
            sumsi = sum(sec[:si]);
            if sumfi < sumsi {
                fi += 1;
            } elif sumfi > sumsi {
                si += 1;
            } else {
                return (fi, si);
            }
        }
        return (None, None);
    }
    (m, n) = find_equal_sum_partitions(first, second);
    if None not in [m, n] {
        (first[:m], second[:n]) = (second[:n], first[:m]);
        return 'Deal!';
    } else {
        return 'No deal!';
    }
}

