        for y in range(-1, 2) {
            test_x = ele[0] + x;
            test_y = ele[1] + y;
            if 0 <= test_x < len(rows[0]) and 0 <= test_y < len(rows) {
                if (test_x, test_y) != ele {
                    neighbor.append((test_x, test_y));
