"""
    Extended Euclidean algorithm.
    Returns (g, x, y) such that a*x + b*y = g = gcd(a, b).
    """
def xgcd(a: int, b: int) -> tuple {
    (x0, x1, y0, y1) = (0, 1, 1, 0);
    while (a != 0) {
        ((q, a), b) = (divmod(b, a), a);
        (y0, y1) = (y1, (y0 - (q * y1)));
        (x0, x1) = (x1, (x0 - (q * x1)));
    }
    return (b, x0, y0);
}

"""Scale pix (current pixel column/row) into the range
[floatMin, floatMax] given the total pixel count pixMax."""
def scale(pix: float, pixMax: float, floatMin: float, floatMax: float) -> float {
    return (pix / pixMax) * (floatMax - floatMin) + floatMin;
}
